let exploreCenter=[40.7558,-73.9883];const mapMarkers=new Map();

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(html){lastFocus=document.activeElement;$('#modalbody').innerHTML=html;$('#modal').classList.remove('hidden');polishIcons($('#modal'));$('.close').focus()}function closeModal(){if(placeChoice){const cancel=placeChoice;placeChoice=null;cancel(null)}$('#modal').classList.add('hidden');lastFocus?.focus()}$('.close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').classList.contains('hidden')){const f=[...$('#modal').querySelectorAll('button,a,input,textarea')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
$('#backhome').onclick=()=>go('home');$('#notifications').onclick=()=>modal('<div class="eyebrow">YOUR NEIGHBORHOOD</div><h2 id="modal-title">A little good news</h2><div class="notification"><b>A brighter block, together</b><p>327 sample supporters are backing better lighting on W 42nd St.</p><small>Community demo</small></div><div class="notification"><b>Your reports stay in your space</b><p>Reports you submit are saved in this browser. They are not sent to city services.</p><small>About this prototype</small></div>');
function head(eyebrow,title,sub){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="badge"><span class="dot"></span> Your neighborhood, connected</div></div>`}
function search(placeholder='Where would you like to go?'){return `<form class="searchbox searchform"><span>⌕</span><input aria-label="Search location" placeholder="${placeholder}" autocomplete="off"><button aria-label="Voice search" class="voice-search" type="button">${icon('mic')}</button></form>`}
function streetViewUrl(coords){if(!KintraServices.pointValid(coords))throw Error('Choose a valid map point.');return 'https://www.google.com/maps/@?api=1&map_action=pano&viewpoint='+encodeURIComponent(coords[0]+','+coords[1])}
function streetViewLink(coords,label='Open Google Street View'){return `<a class="streetview-link" href="${streetViewUrl(coords)}" target="_blank" rel="noopener noreferrer">${icon('camera')} ${esc(label)} ${icon('arrow')}</a>`}
function placePopup(label,coords){return `<div class="place-popup"><b>${esc(label)}</b>${streetViewLink(coords)}<small>Opens Google Maps in a new tab. Street imagery depends on coverage and is not live.</small></div>`}
function updateStreetViewTool(){const link=$('#streetviewmap');if(!link||!map)return;const c=map.getCenter();link.href=streetViewUrl([c.lat,c.lng])}
function mapHTML(full=false){return `<section class="panel map-panel ${full?'map-full':''}"><div class="mapwrap"><div id="map" class="map" aria-label="Interactive neighborhood street map"></div><div class="maptools"><button id="expandmap" aria-label="Expand map" title="Expand map">${icon('expand')}</button><button id="fitroute" aria-label="${full?'Show neighborhood places':'Show entire route'}" title="${full?'Show neighborhood places':'Show entire route'}">${icon('route')}</button><button id="locate" aria-label="Use my location" title="Use my location">${icon('locate')}</button><a id="streetviewmap" class="streetview-tool" href="${streetViewUrl(full?exploreCenter:startPoint)}" target="_blank" rel="noopener noreferrer" aria-label="Open Google Street View at map center in a new tab" title="Street View · opens Google Maps">${icon('camera')}</a></div><div class="routelabel">${icon('shield')} <b>Alternative route</b><span class="route-time">—</span></div><div class="legend"><span><i style="background:#f0b747"></i>Lighting</span><span><i style="background:#ac7de9"></i>Reports</span><span><i style="background:#4ebba3"></i>Safe spots</span><span><i style="background:#568fda"></i>Cameras</span></div></div>${full?`<button class="map-concern" id="mapconcern"><img src="assets/streetlight.jpg" alt="Streetlight at night"><div><h3>Broken Streetlight</h3><p>W 42nd St & 8th Ave</p><span class="status amber">Under Review</span></div>${icon('arrow')}</button>`:''}<div class="road-dot-legend"><label><input id="toggleroads" type="checkbox" ${showRoadDots?'checked':''}> Route dots <span>Demo</span></label><div><span><i style="background:#2388ff"></i>Well-lit</span><span><i style="background:#efbb39"></i>Lighting issue</span><span><i style="background:#a474e8"></i>Report</span><span><i style="background:#34b789"></i>Safe spot</span></div></div><div class="route-key"><button data-route="safer"><i class="swatch safer"></i>Alternative</button><button data-route="fast"><i class="swatch fast"></i>Quickest</button></div><div class="mapcaption"><span>Map © OpenStreetMap · <a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener">Walking API</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">Fix the map</a></span><a href="#map">Explore safety map ↗</a></div></section>`}
function routePanel(){return `<section class="panel routepanel"><div class="sectionlabel">YOUR WALK, YOUR CHOICE</div><div class="routeheading"><span>${icon('route')}</span><h2>Choose your route</h2></div><p class="route-summary">${esc(originLabel)} → ${esc(destination)}</p><button class="choice ${routeMode==='safer'?'selected':''}" data-route="safer"><span>${icon('shield')}</span><div><strong>Alternative route</strong><small class="safer-description">Compared using nearby concerns</small></div><b class="time-safer">—</b></button><button class="choice ${routeMode==='fast'?'selected':''}" data-route="fast"><span>${icon('route')}</span><div><strong>Quickest route</strong><small>Lowest estimated walking time</small></div><b class="time-fast">—</b></button><p class="route-service-status" role="status">${esc(liveNotice)}</p><p class="routenote">Blue is an alternative walking path; orange is the quickest. Nearby concerns are shown for context. Colored pins are sample data plus your own reports, not live incident or lighting coverage. A lower-concern path is not a safety guarantee.</p></section>`}
function routePlanner(){return `<form id="routeform" class="route-planner panel"><div class="planner-fields"><label><span class="start-dot"></span><input aria-label="Starting location" id="origin" value="${esc(originLabel)}" required placeholder="Choose starting point"><button type="button" data-pick="start" aria-label="Pick start on map" title="Pick start on map">${icon('pin')}</button></label><label><span class="end-dot"></span><input aria-label="Destination" id="destination" value="${esc(destination)}" required placeholder="Search destination"><button type="button" data-pick="end" aria-label="Pick destination on map" title="Pick destination on map">${icon('pin')}</button></label></div><button class="primary" id="planroute">Get routes ${icon('route')}</button><p class="planner-help" id="pinhelp">Tap anywhere on the map to choose your start or destination. Drag either pin to move it.</p></form>`}
function home(){return head('','Plan your walk','Choose your start and destination. Compare your two walking routes.')+`<div class="home-layout"><div class="home-top">${routePlanner()}<div class="home-actions"><button id="routesaction"><span>${icon('route')}</span>Routes</button><button data-go="report"><span>${icon('report')}</span>Report</button><button data-go="petitions"><span>${icon('users')}</span>Petitions</button><button id="safespots"><span>${icon('store')}</span>Safe Spots</button></div></div><div class="dashboard">${mapHTML()}<div class="rightcol">${routePanel()}</div></div></div>`}
function neighborhoodPoints(){return [...points,...saved.reports.filter(r=>r.status!=='Resolved'&&Number.isFinite(r.lat)&&Number.isFinite(r.lng)).map((r,i)=>({id:100+i,lat:r.lat,lng:r.lng,type:/light/i.test(r.type)?'Lighting':'Reports',title:r.type,place:r.location,status:r.status,color:/light/i.test(r.type)?'#efb543':'#aa7ced',detail:r.description||'Your locally saved report.'}))]}
function explorerList(){const list=neighborhoodPoints().filter(p=>filter==='All'||p.type===filter);return `<div class="explorer-list-heading"><h2>${filter==='All'?'Neighborhood information':esc(filter)}</h2><span>${list.length} places &amp; concerns</span></div>${list.map(p=>`<button class="explorer-item" data-map-point="${p.id}"><span class="explorer-type" style="--pin:${p.color}">${icon(p.type==='Lighting'?'light':p.type==='Incidents'?'warning':p.type==='Safe spots'?'store':p.type==='Cameras'?'camera':'message')}</span><div><strong>${esc(p.title)}</strong><p>${esc(p.place)}</p><small>${p.id>=100?'Your report':'Sample map information'} · ${esc(p.status)}</small></div>${icon('arrow')}</button>`).join('')||'<p class="empty">No information in this category yet.</p>'}`}
function mapPage(){return head('','Explore your neighborhood','Browse concerns, lighting issues and public places before you go.')+`<div class="explorer-intro"><span>${icon('map')}</span><p>This map is for exploring. To compare walking routes, use <a href="#home">Plan your walk</a>.</p></div><div class="maptop">${search('Search an area or address').replace('searchform','explore-search')}<div class="filters">${['All','Incidents','Reports','Lighting','Safe spots','Cameras'].map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}">${icon({All:'layers',Incidents:'warning',Reports:'message',Lighting:'light','Safe spots':'store',Cameras:'camera'}[x])}${x}</button>`).join('')}</div></div><div class="explore-layout">${mapHTML(true)}<section class="panel explorer-results" id="explorerresults">${explorerList()}</section></div><p class="explorer-note">Map information includes sample pins and reports saved on your device. It is not a live city safety feed.</p>`}
function bindExplorerItems(){document.querySelectorAll('[data-map-point]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.mapPoint),p=neighborhoodPoints().find(p=>p.id===id);if(!p||!map)return;exploreCenter=[p.lat,p.lng];map.setView(exploreCenter,17);mapMarkers.get(id)?.openPopup();$('#map')?.scrollIntoView({behavior:'smooth',block:'center'})})}
function reportPage(){return head('','Report a Safety Concern','Help make your neighborhood safer.')+`<div class="formlayout"><form id="reportform" class="panel reportform"><div class="group"><label>Report Type</label><div class="types">${[['Harassment','users'],['Broken streetlight','streetlight'],['Poor lighting','light'],['Subway security','shield'],['Crosswalk / road','route'],['Other','warning']].map(([n,i])=>`<button type="button" class="type ${reportType===n?'active':''}" data-type="${n}"><span>${icon(i)}</span>${n}</button>`).join('')}</div></div><div class="group"><label for="reportlocation">Location</label><input class="input" id="reportlocation" value="${esc(reportPoint?reportPoint.lat.toFixed(5)+', '+reportPoint.lng.toFixed(5):'W 42nd St & 8th Ave, Manhattan')}" required maxlength="150"></div><div class="group"><label for="description">Description <span class="optional">(Optional)</span></label><textarea class="input" id="description" maxlength="300" placeholder="What happened, when, and what could be improved?"></textarea><div class="charcount"><span id="chars">0</span> / 300</div></div><div class="group"><label for="photo">Add a photo <span class="optional">(optional)</span></label><div class="upload">▧ &nbsp; Add Photo<input type="file" id="photo" accept="image/*"><small class="upload-note">Saved with your report on this device; not uploaded.</small><img id="photopreview" alt="Selected report photo" style="display:none;max-width:100%;max-height:160px;margin-top:12px;border-radius:8px"></div></div><label class="anonymous"><span>${icon('anonymous')}</span><div><b>Submit anonymously</b><p>Your identity is not shown on this report.</p></div><input id="anon" type="checkbox" checked aria-label="Submit anonymously"></label><button class="primary wide">Submit report →</button><p class="subtitle" style="font-size:10px;margin-top:12px">Saved on this device for your class demo. Not sent to city services.</p></form><div class="tipcard"><div class="eyebrow">A NEIGHBORLY NOTE</div><h3>Your experience matters.</h3><p>Little things can make a big difference. Share specific locations and what you think could help.</p><small>Avoid including personal details about yourself or other people. This prototype is not monitored for emergencies. In an immediate emergency, contact local emergency services.</small></div></div>`}
function petitionsPage(){const list=petitions.filter(p=>petitionFilter==='Nearby'?p.tag!=='Completed':p.tag.toLowerCase()===petitionFilter.toLowerCase());return head('','Community Petitions','Support improvements for a safer neighborhood.')+`<div class="filters">${['Nearby','In progress','Completed'].map(x=>`<button class="chip ${petitionFilter===x?'active':''}" data-petfilter="${x}">${x}</button>`).join('')}</div><div class="cards">${list.map(p=>{const signed=saved.signed.includes(p.id),count=p.count+Number(signed);return `<article class="panel petition"><button class="petition-open" data-petition="${p.id}" aria-label="View ${esc(p.title)}"></button><div class="petition-image"><img src="${p.img}" alt="${p.alt}" loading="lazy"><span class="status ${p.tag==='Completed'?'green':''}">${p.tag}</span></div><div class="petitionbody"><div class="eyebrow" style="font-size:8px;letter-spacing:1px">${p.place}</div><h2>${p.title}</h2><span class="card-chevron">${icon('arrow')}</span><p>${p.desc}</p><div class="counts"><b>${icon('users')} ${count} supporters${signed?' · Supported':''}</b><span>Goal ${p.goal}</span></div><div class="progress"><span style="width:${Math.min(100,count/p.goal*100)}%"></span></div><button class="secondary wide petition-support" data-petition="${p.id}" ${p.tag==='Completed'?'disabled':''}>${p.tag==='Completed'?'✓ Completed':signed?'✓ Supported · View petition':'Support this petition →'}</button></div></article>`}).join('')}</div><p class="subtitle" style="font-size:10px;margin-top:20px">Sample petitions for the AIS prototype. Support is saved in this browser; no petition is sent to an authority.</p>`}
const seedReports=[{type:'Broken streetlight',location:'W 42nd St & 8th Ave',status:'Resolved',date:'Oct 28, 2026',description:'The streetlight has been repaired. Sample report.'},{type:'Poor lighting',location:'W 40th St',status:'Under review',date:'Oct 25, 2026',description:'Your concern has been received. Sample report.'},{type:'Subway station security',location:'8th Ave Station',status:'Submitted',date:'Oct 22, 2026',description:'Your report has been submitted. Sample report.'}];
function reportImage(r){if(typeof r.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(r.photo))return {src:r.photo,label:'Your uploaded photo'};const type=r.type.toLowerCase(),text=(r.type+' '+(r.description||'')).toLowerCase();let src='assets/concern.svg';if(/harass|follow|stalk|personal safety/.test(type))src='assets/personal-safety.jpg';else if(/poor light|dark|visibility/.test(type))src='assets/poor-lighting.jpg';else if(/streetlight|street light|lamp/.test(type))src='assets/streetlight.jpg';else if(/subway|station|security/.test(type))src='assets/subway.jpg';else if(/crosswalk|crossing|road|pothole|traffic/.test(type))src='assets/crosswalk.jpg';else if(/trash|rubbish|waste|garbage|litter|obstruct/.test(text))src='assets/waste.jpg';else if(/harass|follow|stalk/.test(text))src='assets/personal-safety.jpg';else if(/streetlight|street light|lamp/.test(text))src='assets/streetlight.jpg';else if(/dark|light|alley/.test(text))src='assets/poor-lighting.jpg';else if(/subway|station/.test(text))src='assets/subway.jpg';else if(/crosswalk|road|traffic/.test(text))src='assets/crosswalk.jpg';return {src,label:src.endsWith('.svg')?'General concern illustration':'Representative image — not evidence of this report'}}
function profile(){const own=saved.reports,all=[...own,...(showSamples?seedReports:[])],visible=all.map((r,i)=>({r,i})).filter(({r})=>statusFilter==='All'||(statusFilter==='Open'?r.status!=='Resolved':r.status==='Resolved'));return head('','Your Space','Your reports, your progress, your neighborhood.')+`<section class="profile-summary panel"><div class="profile-person"><span class="profile-avatar">${icon('user')}</span><div><h2>${esc(saved.name||'Your space')}</h2><p>Community member · Saved on this device</p></div><button class="textbtn" id="editname">Edit name</button></div><div class="profile-stats"><button data-own-status="All"><strong>${own.length}</strong><span>Your reports</span></button><button data-own-status="Open"><strong>${own.filter(r=>r.status!=='Resolved').length}</strong><span>Open</span></button><button data-own-status="Resolved"><strong>${own.filter(r=>r.status==='Resolved').length}</strong><span>Resolved by you</span></button><button data-show-petitions><strong>${saved.signed.length}</strong><span>Petitions supported</span></button></div></section><h2 class="my-reports-heading">My Reports</h2><div class="filters">${['Reports','Petitions'].map(x=>`<button class="chip ${profileTab===x?'active':''}" data-profiletab="${x}">${x}</button>`).join('')}</div>${profileTab==='Reports'?`<div class="status-filters">${['All','Open','Resolved'].map(x=>`<button class="chip ${statusFilter===x?'active':''}" data-status="${x}">${x}</button>`).join('')}</div><label class="sample-toggle"><input id="showsamples" type="checkbox" ${showSamples?'checked':''}> Show sample reports</label><p class="profile-explainer">${own.length?'Your submissions appear first.':'You have not submitted a report yet.'} You can toggle sample reports to explore the possible statuses. New reports are not sent to city services.</p><section class="panel">${visible.length?visible.map(({r,i})=>{const image=reportImage(r);return `<div class="reportrow"><img class="report-thumb" src="${image.src}" alt="${esc(image.label)}"><div><h3>${esc(r.type)}</h3><p>${esc(r.location)}</p><small class="record-origin">${i<own.length?'Your report':'Sample report'}</small></div><span class="status ${r.status==='Resolved'?'green':r.status==='Under review'?'amber':''}">${esc(r.status)}</span><time>${esc(r.date)}</time><p class="report-description">${esc(r.description||'Your report has been submitted.')}</p><button class="textbtn" data-reportdetail="${i}" aria-label="View report details">${icon('arrow')}</button></div>`}).join(''):'<div class="empty">No reports match this status.</div>'}</section>`:`<section class="panel">${saved.signed.length?saved.signed.map(id=>{const p=petitions.find(p=>p.id===id);if(!p)return '';return `<div class="supported-petition"><img src="${p.img}" alt="${p.alt}"><div><h3>${p.title}</h3><p>${p.count+1} sample supporters</p><span class="status green">Supported</span></div><button class="textbtn" data-petition="${p.id}">View ${icon('arrow')}</button></div>`}).join(''):'<div class="empty">Your voice belongs here.<p>Support a petition to see it in your space.</p><a href="#petitions">Explore petitions →</a></div>'}</section>`}`}
